import (
	"fmt"
	"sort"
)

type Interval[T comparable] struct {
	Start T
	End   T
}

func mergeIntervals[T comparable](intervals []Interval[T]) []Interval[T] {
	if len(intervals) == 0 {
		return []Interval[T]{}
	}

	// Sort intervals by start
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i].Start < intervals[j].Start
	})

	merged := []Interval[T]{intervals[0]}
	for i := 1; i < len(intervals); i++ {
		last := merged[len(merged)-1]
		current := intervals[i]

		// Check if current starts before or at the end of last
		if current.Start <= last.End {
			// Merge them
			newEnd := last.End
			if current.End > newEnd {
				newEnd = current.End
			}
			merged[len(merged)-1] = Interval[T]{Start: last.Start, End: newEnd}
		} else {
			merged = append(merged, current)
		}
	}

	return merged
}

